Value.Calculation:
JSONSetElement ( "{}" ;
	[ "root"  ; ScriptLog::RootScript ; JSONString ] ;
	[ "sess"  ; ScriptLog::SessionID  ; JSONString ] ;
	[ "trace" ; ScriptLog::TraceID    ; JSONString ] ;
	[ "rc"    ; ScriptLog::RowCount   ; JSONNumber ] ;
	[ "ts"    ; ScriptLog::CreatedAt  ; JSONString ]
)
